input.command:
cd "C:\Users\Billy\AppData\Local\Temp\lcm-live-mb6mbk2q\provider-s05-operator-redrive" && python -c "
import re, json, csv

base = 'maintenance/inputs/provider-s05/redrive-requests/'

# md
md = {}
with open(base+'provider-s05-t04-evidence-01.md', encoding='utf-8') as f:
    for line in f:
        m = re.match(r'- \*\*(provider-s05-t04-\d+)\*\* \| System: ([^|]+) \| Status: ([^|]+) \| Evidence: (.+)', line.strip())
        if m:
            cid, system, status, note = m.groups()
            md[cid] = (system.strip(), status.strip(), note.strip())

# jsonl
jl = {}
with open(base+'provider-s05-t04-evidence-02.jsonl', encoding='utf-8') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        jl[obj['case']] = (obj['system'], obj['status'], obj['note'])

# csv
cv = {}
with open(base+'provider-s05-t04-evidence-03.csv', encoding='utf-8', newline='') as f:
    for row in csv.DictReader(f):
        cv[row['case']] = (row['system'], row['status'], row['note'])

# yaml (custom simple parser given known structure)
yl = {}
with open(base+'provider-s05-t04-evidence-04.yaml', encoding='utf-8') as f:
    lines = [l.rstrip('\r\n') for l in f]
cur = {}
cid = None
for line in lines:
    s = line.strip()
    if s.startswith('- case:'):
        if cid:
            yl[cid] = (cur.get('system'), cur.get('status'), cur.get('note'))
        cid = s.split(':',1)[1].strip()
        cur = {}
    elif s.startswith('system:'):
        cur['system'] = s.split(':',1)[1].strip()
    elif s.startswith('status:'):
        cur['status'] = s.split(':',1)[1].strip()
    elif s.startswith('note:'):
        cur['note'] = s.split(':',1)[1].strip().strip('\"')
if cid:
    yl[cid] = (cur.get('system'), cur.get('status'), cur.get('note'))

print('md entries', len(md), 'jsonl entries', len(jl), 'csv entries', len(cv), 'yaml entries', len(yl))

common_ids = sorted(set(md) & set(jl) & set(cv) & set(yl), key=lambda x: int(x.split('-')[-1]))
print('common ids count', len(common_ids), 'first', common_ids[0], 'last', common_ids[-1])

mismatches = []
for cid in common_ids:
    vals = {'md': md[cid], 'jsonl': jl[cid], 'csv': cv[cid], 'yaml': yl[cid]}
    if len(set(vals.values())) > 1:
        mismatches.append((cid, vals))

print('mismatches among common ids:', len(mismatches))
for m in mismatches[:5]:
    print(m)
"

