import re, json, csv

def parse_md(fname):
    data = {}
    with open(fname, "r", encoding="utf-8") as f:
        for line in f:
            m = re.match(r"- \*\*(provider-s05-t08-\d{6})\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)$", line.strip())
            if m:
                case, system, status, note = m.groups()
                data[case] = {"system": system, "status": status, "note": note}
    return data

def parse_jsonl(fname):
    data = {}
    with open(fname, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            data[obj["case"]] = {"system": obj["system"], "status": obj["status"], "note": obj["note"]}
    return data

def parse_csv(fname):
    data = {}
    with open(fname, "r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            data[row["case"]] = {"system": row["system"], "status": row["status"], "note": row["note"]}
    return data

def parse_yaml(fname):
    data = {}
    with open(fname, "r", encoding="utf-8") as f:
        lines = [l.rstrip("\n").rstrip("\r") for l in f]
    case = None
    current = {}
    for line in lines:
        s = line.strip()
        if s.startswith("- case:"):
            if case is not None:
                data[case] = current
            case = s.split(":", 1)[1].strip()
            current = {}
        elif s.startswith("system:"):
            current["system"] = s.split(":", 1)[1].strip()
        elif s.startswith("status:"):
            current["status"] = s.split(":", 1)[1].strip()
        elif s.startswith("note:"):
            current["note"] = s.split(":", 1)[1].strip().strip('"')
    if case is not None:
        data[case] = current
    return data

md = parse_md("provider-s05-t08-evidence-01.md")
jsonl = parse_jsonl("provider-s05-t08-evidence-02.jsonl")
csvd = parse_csv("provider-s05-t08-evidence-03.csv")
yaml = parse_yaml("provider-s05-t08-evidence-04.yaml")

print("parsed counts: md=%d jsonl=%d csv=%d yaml=%d" % (len(md), len(jsonl), len(csvd), len(yaml)))

common = set(md) & set(jsonl) & set(csvd) & set(yaml)
print("common cases across all four:", len(common))

mismatches = []
for case in sorted(common):
    rows = {"md": md[case], "jsonl": jsonl[case], "csv": csvd[case], "yaml": yaml[case]}
    system_vals = {k: v["system"] for k, v in rows.items()}
    status_vals = {k: v["status"] for k, v in rows.items()}
    note_vals = {k: v["note"] for k, v in rows.items()}
    if len(set(system_vals.values())) > 1 or len(set(status_vals.values())) > 1 or len(set(note_vals.values())) > 1:
        mismatches.append((case, system_vals, status_vals))

print("mismatches among common cases:", len(mismatches))
for m in mismatches[:10]:
    print(m)

rows = [(csvd[c]["system"], csvd[c]["status"]) for c in sorted(csvd, key=lambda x: int(x.rsplit("-",1)[1]))]
cycle = rows[:4]
deviations = sum(1 for i, pair in enumerate(rows) if pair != cycle[i % 4])
print("csv cycle:", cycle, "deviations:", deviations, "total rows:", len(rows))
