cd "maintenance/inputs/provider-s05/interruption-cases" && python << 'EOF'
import re, json, csv

md_cases = {}
with open("provider-s05-t11-evidence-01.md", encoding="utf-8") as f:
    for line in f:
        m = re.match(r"- \*\*(provider-s05-t11-\d+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)$", line.strip())
        if m:
            case, system, status, note = m.groups()
            md_cases[case] = {"system": system, "status": status, "note": note}

jsonl_cases = {}
with open("provider-s05-t11-evidence-02.jsonl", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        jsonl_cases[d["case"]] = {"system": d["system"], "status": d["status"], "note": d["note"]}

csv_cases = {}
with open("provider-s05-t11-evidence-03.csv", encoding="utf-8", newline="") as f:
    reader = csv.DictReader(f)
    csv_rows = list(reader)
    for row in csv_rows:
        csv_cases[row["case"]] = {"system": row["system"], "status": row["status"], "note": row["note"]}

yaml_cases = {}
with open("provider-s05-t11-evidence-04.yaml", encoding="utf-8") as f:
    lines = f.readlines()
cur = {}
for line in lines:
    line = line.rstrip("\n").rstrip("\r")
    if line.startswith("- case:"):
        if cur.get("case"):
            yaml_cases[cur["case"]] = {"system": cur.get("system"), "status": cur.get("status"), "note": cur.get("note")}
        cur = {"case": line.split(":", 1)[1].strip()}
    elif line.strip().startswith("system:"):
        cur["system"] = line.split(":", 1)[1].strip()
    elif line.strip().startswith("status:"):
        cur["status"] = line.split(":", 1)[1].strip()
    elif line.strip().startswith("note:"):
        cur["note"] = line.split(":", 1)[1].strip().strip('"')
if cur.get("case"):
    yaml_cases[cur["case"]] = {"system": cur.get("system"), "status": cur.get("status"), "note": cur.get("note")}

def num(case_id):
    return int(case_id.rsplit("-", 1)[1])

print("md count:", len(md_cases), "range:", min(map(num, md_cases)), "-", max(map(num, md_cases)))
print("jsonl count:", len(jsonl_cases), "range:", min(map(num, jsonl_cases)), "-", max(map(num, jsonl_cases)))
print("csv count:", len(csv_cases), "range:", min(map(num, csv_cases)), "-", max(map(num, csv_cases)))
print("yaml count:", len(yaml_cases), "range:", min(map(num, yaml_cases)), "-", max(map(num, yaml_cases)))

def gaps(cases):
    nums = sorted(map(num, cases))
    missing = [n for n in range(nums[0], nums[-1]+1) if n not in set(nums)]
    return missing

print("md gaps:", gaps(md_cases))
print("jsonl gaps:", gaps(jsonl_cases))
print("csv gaps:", gaps(csv_cases))
print("yaml gaps:", gaps(yaml_cases))

common = set(md_cases) & set(jsonl_cases) & set(csv_cases) & set(yaml_cases)
print("common count:", len(common))

mismatches = []
for c in sorted(common, key=num):
    vals = {"md": md_cases[c], "jsonl": jsonl_cases[c], "csv": csv_cases[c], "yaml": yaml_cases[c]}
    systems = {k: v["system"] for k, v in vals.items()}
    statuses = {k: v["status"] for k, v in vals.items()}
    if len(set(systems.values())) > 1 or len(set(statuses.values())) > 1:
        mismatches.append((c, vals))

print("mismatches among common cases:", len(mismatches))
for m in mismatches[:10]:
    print(m)

cycle_seq = [(row["system"], row["status"]) for row in csv_rows]
first4 = cycle_seq[:4]
deviations = [ (i,pair) for i,pair in enumerate(cycle_seq) if pair != first4[i % 4] ]
print("csv cycle first4:", first4)
print("csv cycle deviations:", len(deviations))
print("csv total rows:", len(cycle_seq))
print("last row:", csv_rows[-1]["case"], csv_rows[-1]["system"], csv_rows[-1]["status"])
EOF

