import re, json, csv

# Parse md
md_cases = {}
with open("provider-s05-t13-evidence-01.md", encoding="utf-8") as f:
    for line in f:
        m = re.match(r"- \*\*(\S+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)$", line.strip())
        if m:
            case, system, status, note = m.groups()
            md_cases[case] = {"system": system, "status": status, "note": note}

# Parse jsonl
jsonl_cases = {}
with open("provider-s05-t13-evidence-02.jsonl", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        jsonl_cases[obj["case"]] = {"system": obj["system"], "status": obj["status"], "note": obj["note"]}

# Parse csv
csv_cases = {}
with open("provider-s05-t13-evidence-03.csv", encoding="utf-8", newline="") as f:
    reader = csv.DictReader(f)
    for row in reader:
        csv_cases[row["case"]] = {"system": row["system"], "status": row["status"], "note": row["note"]}

# Parse yaml (custom block parser)
yaml_cases = {}
with open("provider-s05-t13-evidence-04.yaml", encoding="utf-8") as f:
    lines = [l.rstrip("\r\n") for l in f]
current = {}
case_id = None
for line in lines:
    stripped = line.strip()
    if stripped.startswith("- case:"):
        if case_id is not None:
            yaml_cases[case_id] = current
        case_id = stripped.split(":", 1)[1].strip()
        current = {}
    elif stripped.startswith("system:"):
        current["system"] = stripped.split(":", 1)[1].strip()
    elif stripped.startswith("status:"):
        current["status"] = stripped.split(":", 1)[1].strip()
    elif stripped.startswith("note:"):
        current["note"] = stripped.split(":", 1)[1].strip().strip('"')
if case_id is not None:
    yaml_cases[case_id] = current

print("counts:", "md=",len(md_cases), "jsonl=",len(jsonl_cases), "csv=",len(csv_cases), "yaml=",len(yaml_cases))

# Case id ranges
def id_range(d):
    nums = sorted(int(c.split("-")[-1]) for c in d)
    return nums[0], nums[-1], len(nums) == (nums[-1]-nums[0]+1)

print("md range:", id_range(md_cases))
print("jsonl range:", id_range(jsonl_cases))
print("csv range:", id_range(csv_cases))
print("yaml range:", id_range(yaml_cases))

common = set(md_cases) & set(jsonl_cases) & set(csv_cases) & set(yaml_cases)
print("common count:", len(common))

mismatches = []
for case in sorted(common):
    m, j, c, y = md_cases[case], jsonl_cases[case], csv_cases[case], yaml_cases[case]
    for field in ("system", "status", "note"):
        vals = {m[field], j[field], c[field], y[field]}
        if len(vals) > 1:
            mismatches.append((case, field, m[field], j[field], c[field], y[field]))

print("mismatches:", len(mismatches))
for mm in mismatches[:20]:
    print(mm)

# csv-only extra cases (cases present in csv but not others)
extra_csv = set(csv_cases) - common
print("csv-only extra cases:", sorted(extra_csv))
for c in sorted(extra_csv):
    print(c, csv_cases[c]["system"], csv_cases[c]["status"])

# cycle check across full csv ordered by numeric id
ordered_csv = sorted(csv_cases.items(), key=lambda kv: int(kv[0].split("-")[-1]))
cycle = [(v["system"], v["status"]) for k, v in ordered_csv[:4]]
print("first 4 (system,status) pairs in csv:", cycle)
deviations = 0
for i, (k, v) in enumerate(ordered_csv):
    expected = cycle[i % 4]
    if (v["system"], v["status"]) != expected:
        deviations += 1
        print("deviation at", k, (v["system"], v["status"]), "expected", expected)
print("cycle deviations:", deviations)
EOF

