def connect(database: str | Path) -> sqlite3.Connection:
    # check_same_thread=False: the HTTP server opens this connection on the
    # thread that builds it, then serves requests sequentially on whichever
    # thread calls serve_forever(). Those are allowed to differ; the server's
    # single-request-at-a-time handling (see server.py) is what keeps access
    # safe, not thread affinity.
    conn = sqlite3.connect(str(database), timeout=5.0, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    conn.execute("PRAGMA journal_mode = WAL")
    conn.execute("PRAGMA synchronous = FULL")
    conn.execute("PRAGMA busy_timeout = 5000")
    init_db(conn)
    return conn


def init_db(conn: sqlite3.Connection) -> None:
    with conn:
        conn.executescript(SCHEMA)


def ensure_organization(conn: sqlite3.Connection, organization_id: str, now: str) -> None:
    with conn:
        conn.execute(
            "INSERT OR IGNORE INTO organizations(organization_id, created_at) VALUES (?, ?)",
            (organization_id, now),
        )


def get_account(conn: sqlite3.Connection, account_id: str) -> sqlite3.Row | None:
    return conn.execute(
        "SELECT * FROM accounts WHERE account_id = ?", (account_id,)
    ).fetchone()


def require_account(conn: sqlite3.Connection, account_id: str) -> sqlite3.Row:
    row = get_account(conn, account_id)
    if row is None:
        raise NotFoundError(f"unknown account: {account_id}")
    return row


def get_current_email(conn: sqlite3.Connection, account_id: str) -> str | None:
    row = conn.execute(
        "SELECT email FROM email_ownership WHERE account_id = ? AND status = 'current'",
        (account_id,),
    ).fetchone()
    return row["email"] if row else None


def get_email_history(conn: sqlite3.Connection, account_id: str) -> list[sqlite3.Row]:
    return conn.execute(
        "SELECT email, status, acquired_at, released_at FROM email_ownership "
        "WHERE account_id = ? ORDER BY ownership_id ASC",
        (account_id,),
    ).fetchall()


def find_account_by_current_email(
    conn: sqlite3.Connection, organization_id: str, email: str
) -> sqlite3.Row | None:
    return conn.execute(
        "SELECT a.* FROM accounts a "
        "JOIN email_ownership eo ON eo.account_id = a.account_id "
        "WHERE eo.organization_id = ? AND eo.email = ? AND eo.status = 'current'",
        (organization_id, email),
    ).fetchone()


def get_operator(conn: sqlite3.Connection, operator_id: str) -> sqlite3.Row | None:
    return conn.execute(
        "SELECT * FROM operators WHERE operator_id = ?", (operator_id,)
    ).fetchone()


def count_pending_notifications(conn: sqlite3.Connection, account_id: str) -> int:
    row = conn.execute(
        "SELECT COUNT(*) AS n FROM pending_notifications WHERE account_id = ? AND status = 'pending'",
        (account_id,),
    ).fetchone()
    return int(row["n"])


def raise_if_email_taken(conn: sqlite3.Connection, organization_id: str, email: str) -> None:
    existing = conn.execute(
        "SELECT account_id FROM email_ownership WHERE organization_id = ? AND email = ? AND status = 'current'",
        (organization_id, email),
    ).fetchone()
    if existing is not None:
        raise ConflictError(f"email already in use within organization: {email}")

"""Exceptions shared across accountsvc modules."""
from __future__ import annotations


class AccountServiceError(Exception):
    """Base class for errors the CLI and HTTP layer know how to render."""


class ValidationError(AccountServiceError):
    """Input failed a bounds or format check."""


class NotFoundError(AccountServiceError):
    """A referenced organization, account, operator, or record does not exist."""


class ConflictError(AccountServiceError):
    """The requested change would violate a uniqueness or identity rule."""


class AuthError(AccountServiceError):
    """The caller did not present valid administrative credentials."""


class PolicyError(AccountServiceError):
    """An operator action was rejected by redrive approval policy."""

"""Bounded-input validation shared by the CLI and the loopback HTTP service.

Every value that crosses a trust boundary (CLI argv, HTTP request bodies)
passes through here first. Limits are deliberately small: this service only
ever needs short identifiers, RFC-bounded email addresses, and short-lived
tokens.
"""
from __future__ import annotations

import re
from datetime import datetime, timezone

from .errors import ValidationError

IDENTIFIER_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$")
EMAIL_RE = re.compile(r"^[^@\s]{1,64}@[^@\s]{1,255}\.[^@\s]{1,24}$")

MAX_EMAIL_LENGTH = 320
MAX_IDENTIFIER_LENGTH = 64
MAX_TOKEN_LENGTH = 128
MAX_DISPLAY_NAME_LENGTH = 128
MAX_APPROVAL_REQUEST_IDS = 500

DECISIONS = ("previewed", "approved", "rejected")


def validate_identifier(label: str, value: object) -> str:
    """Validate an organization/account/operator/decision/batch id."""

    if not isinstance(value, str):
        raise ValidationError(f"{label} must be a string")
    if not IDENTIFIER_RE.match(value):
        raise ValidationError(
            f"{label} must be 1-{MAX_IDENTIFIER_LENGTH} characters of "
            "letters, digits, '.', '_', or '-', starting with a letter or digit"
        )
    return value


def validate_email(value: object) -> str:
    if not isinstance(value, str):
        raise ValidationError("email must be a string")
    if len(value) > MAX_EMAIL_LENGTH:
        raise ValidationError(f"email must be at most {MAX_EMAIL_LENGTH} characters")
    if not EMAIL_RE.match(value):
        raise ValidationError("email is not a valid address")
    return value


def validate_decision(value: object) -> str:
    if value not in DECISIONS:
        raise ValidationError(f"decision must be one of {', '.join(DECISIONS)}")
    return value  # type: ignore[return-value]


def validate_token(value: object) -> str:
    if not isinstance(value, str) or not value:
        raise ValidationError("token must be a non-empty string")
    if len(value) > MAX_TOKEN_LENGTH:
        raise ValidationError(f"token must be at most {MAX_TOKEN_LENGTH} characters")
    return value


def validate_ttl_seconds(value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValidationError("recovery_ttl_seconds must be a positive integer")
    if value <= 0:
        raise ValidationError("recovery_ttl_seconds must be a positive integer")
    return value


def validate_age_range(min_age_seconds: object, max_age_seconds: object) -> tuple[int, int]:
    for label, value in (("min_age_seconds", min_age_seconds), ("max_age_seconds", max_age_seconds)):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError(f"{label} must be a non-negative integer")
        if value < 0:
            raise ValidationError(f"{label} must be a non-negative integer")
    if min_age_seconds > max_age_seconds:
        raise ValidationError("min_age_seconds must be less than or equal to max_age_seconds")
    return min_age_seconds, max_age_seconds  # type: ignore[return-value]


def validate_request_ids(value: object) -> tuple[str, ...]:
    if not isinstance(value, (list, tuple)):
        raise ValidationError("request_ids must be a list of strings")
    if not value:
        raise ValidationError("request_ids must be a non-empty list")
    if len(value) > MAX_APPROVAL_REQUEST_IDS:
        raise ValidationError(f"request_ids must contain at most {MAX_APPROVAL_REQUEST_IDS} entries")
    validated: list[str] = []
    seen: set[str] = set()
    for item in value:
        request_id = validate_identifier("request_ids[]", item)
        if request_id in seen:
            raise ValidationError(f"duplicate request id in request_ids: {request_id}")
        seen.add(request_id)
        validated.append(request_id)
    return tuple(validated)


def validate_display_name(value: object) -> str | None:
    if value is None:
        return None
    if not isinstance(value, str) or not value.strip():
        raise ValidationError("display_name must be a non-empty string")
    if len(value) > MAX_DISPLAY_NAME_LENGTH:
        raise ValidationError(f"display_name must be at most {MAX_DISPLAY_NAME_LENGTH} characters")
    return value


def now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def parse_iso(value: str) -> datetime:
    try:
        text = value.strip()
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        parsed = datetime.fromisoformat(text)
    except ValueError as exc:
        raise ValidationError(f"invalid timestamp: {value!r}") from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)

"""Secret generation and comparison helpers.

Recovery tokens are bearer secrets: only their SHA-256 hash is ever written
to disk, mirroring how the bearer administration token is compared without
ever touching a database.
"""
from __future__ import annotations

import hashlib
import hmac
import secrets

TOKEN_BYTES = 32


def generate_token() -> str:
    """Return a fresh single-use recovery token."""

    return secrets.token_urlsafe(TOKEN_BYTES)


def hash_token(token: str) -> str:
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def tokens_equal(a: str, b: str) -> bool:
    return hmac.compare_digest(a.encode("utf-8"), b.encode("utf-8"))

